import{_ as a,c as s,o as t,a2 as r}from"./chunks/framework.PGES7OoM.js";const l=JSON.parse('{"title":"Receive assets privately","description":"","frontmatter":{"rawMarkdown":"# Receive assets privately\\n\\nOne of the most unique things about Curvy is how easy it is to share payment instructions with senders.\\n\\nPeople sending you assets never need to know what Curvy is, how it works, or to open the Curvy App.\\nThey just need to copy and paste your public URL or ENS address (which is also ideally very easy to remember).\\n\\n> [!TIP]\\n> You can receive assets on any network listed in the [supported networks](/for-users/#supported-networks-and-tokens). Curvy will automatically bridge your funds using LiFi and shield them on Arbitrum.\\n\\nBelow are three ways you can share payment instructions with senders so that you can receive assets automatically shielded in Curvy.\\n\\nEverything you need to share is on the **Receive** page of the Curvy App: your Curvy name, the link to your receiving page, and a QR code of it.\\n\\n## By sharing your ENS\\n\\nThe easiest way for someone to send you assets is by using your Curvy ID in an ENS-compatible wallet such as Rabby or MetaMask.\\n\\nThe sender can simply enter your Curvy ID, for example `your-curvy-id.curvy.name`, as the recipient for a new transaction.\\nTheir wallet resolves it to a fresh private address, so nothing about you appears on-chain.\\n\\n## By sharing your public URL\\n\\nIf the sender\'s wallet doesn\'t support ENS, they can always open your public URL\\n\\n```\\nhttps://your-curvy-id.curvy.name\\n```\\n\\nchoose EVM or Solana, then **Get payment address**, and copy the generated address to the wallet of their choice.\\nThe same address works on any [supported network](/for-users/#supported-networks-and-tokens) of that kind.\\nThe address is single-use: only the first transfer to it is forwarded automatically.\\n\\n## By generating a private address\\n\\nIf you are, for example, withdrawing funds from an exchange, you will not be able to enter the ENS as the withdrawal address or send a URL through a message, as it\'s an automated process.\\n\\nIn this case, open the **Receive** page in the Curvy App, choose **Create one-time address** (EVM or Solana, depending on where the exchange will send from),\\nand copy the newly generated private address to the withdrawal form.\\n","rawMarkdownPath":"/_raw/for-users/receive-assets-privately.md","rawMarkdownTitle":"Receive assets privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/receive-assets-privately.md"},"headers":[],"relativePath":"for-users/receive-assets-privately.md","filePath":"for-users/receive-assets-privately.md","lastUpdated":1791449043000}'),n={name:"for-users/receive-assets-privately.md"};function o(i,e,d,h,u,p){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="receive-assets-privately" tabindex="-1">Receive assets privately <a class="header-anchor" href="#receive-assets-privately" aria-label="Permalink to &quot;Receive assets privately&quot;">​</a></h1><p>One of the most unique things about Curvy is how easy it is to share payment instructions with senders.</p><p>People sending you assets never need to know what Curvy is, how it works, or to open the Curvy App. They just need to copy and paste your public URL or ENS address (which is also ideally very easy to remember).</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>You can receive assets on any network listed in the <a href="/for-users/#supported-networks-and-tokens">supported networks</a>. Curvy will automatically bridge your funds using LiFi and shield them on Arbitrum.</p></div><p>Below are three ways you can share payment instructions with senders so that you can receive assets automatically shielded in Curvy.</p><p>Everything you need to share is on the <strong>Receive</strong> page of the Curvy App: your Curvy name, the link to your receiving page, and a QR code of it.</p><h2 id="by-sharing-your-ens" tabindex="-1">By sharing your ENS <a class="header-anchor" href="#by-sharing-your-ens" aria-label="Permalink to &quot;By sharing your ENS&quot;">​</a></h2><p>The easiest way for someone to send you assets is by using your Curvy ID in an ENS-compatible wallet such as Rabby or MetaMask.</p><p>The sender can simply enter your Curvy ID, for example <code>your-curvy-id.curvy.name</code>, as the recipient for a new transaction. Their wallet resolves it to a fresh private address, so nothing about you appears on-chain.</p><h2 id="by-sharing-your-public-url" tabindex="-1">By sharing your public URL <a class="header-anchor" href="#by-sharing-your-public-url" aria-label="Permalink to &quot;By sharing your public URL&quot;">​</a></h2><p>If the sender&#39;s wallet doesn&#39;t support ENS, they can always open your public URL</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-curvy-id.curvy.name</span></span></code></pre></div><p>choose EVM or Solana, then <strong>Get payment address</strong>, and copy the generated address to the wallet of their choice. The same address works on any <a href="/for-users/#supported-networks-and-tokens">supported network</a> of that kind. The address is single-use: only the first transfer to it is forwarded automatically.</p><h2 id="by-generating-a-private-address" tabindex="-1">By generating a private address <a class="header-anchor" href="#by-generating-a-private-address" aria-label="Permalink to &quot;By generating a private address&quot;">​</a></h2><p>If you are, for example, withdrawing funds from an exchange, you will not be able to enter the ENS as the withdrawal address or send a URL through a message, as it&#39;s an automated process.</p><p>In this case, open the <strong>Receive</strong> page in the Curvy App, choose <strong>Create one-time address</strong> (EVM or Solana, depending on where the exchange will send from), and copy the newly generated private address to the withdrawal form.</p>',16)])])}const c=a(n,[["render",o]]);export{l as __pageData,c as default};
